  /* the seed's own colours */
  const HAND_SKINS = [['#e0c8a8', '#c0a484'], ['#d8b890', '#b8946e'], ['#c9955a', '#a87a46'], ['#a87f5e', '#8a6248'], ['#8a6248', '#6e4a36'], ['#6e4a36', '#54382a']];
  const HAND_HAIRS = [['#1a1410', '#0e0c0a'], ['#2a2118', '#1a1410'], ['#5a4630', '#3a2e1e'], ['#8a5a32', '#6e4424'], ['#c9a05a', '#a08050'], ['#8a8578', '#6e6a5e'], ['#d8d2bd', '#b8b29d']];
  function handFace(seed, trade) {
    let a = seed >>> 0; const rng = () => { a = (a + 0x6D2B79F5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
    const pick = arr => arr[Math.floor(rng() * arr.length)];
    const T = HANDS.trades[trade] || HANDS.trades.courier;
    const skin = pick(HAND_SKINS), old = rng() < 0.18, hair = old ? (rng() < 0.5 ? HAND_HAIRS[5] : HAND_HAIRS[6]) : pick(HAND_HAIRS.slice(0, 5));
    const hairKey = pick(['crop', 'crop', 'long', 'bun', 'curls', 'buzz', 'swept', 'braid', old ? 'bald' : 'crop']);
    const jaw = rng() < 0.4 ? 'square' : 'oval';
    const facial = pick(['none', 'none', 'none', 'stubble', 'moustache', 'beard', 'full']);
    const eyes = old ? (rng() < 0.3 && !T.noGlasses ? 'glasses' : 'tired') : pick(['plain', 'plain', 'plain', 'close', 'tired', rng() < 0.3 && !T.noGlasses ? 'glasses' : 'plain']);
    const mix = (h1, h2) => { const p = x => [1, 3, 5].map(i => parseInt(x.slice(i, i + 2), 16)); const A = p(h1), B = p(h2); return '#' + A.map((v, i) => Math.round((v + B[i]) / 2).toString(16).padStart(2, '0')).join(''); };
    const pal = { O: '#12161c', S: skin[0], s: skin[1], e: '#2a2118', m: mix(skin[1], '#7a3a2a'), H: hair[0], h: hair[1], B: hair[0], b: mix(skin[1], hair[0]), W: '#e8e0c8', w: '#c9c3a8', G: '#a5c6e4', g: '#5a5f66', C: '#4a4f57', c: '#383c44', ...T.pal };
    const rows = HANDS.base.map(r => r.split(''));
    const lay = (L, from = 0) => { if (!L) return; L.forEach((r, y) => { if (y < from) return; for (let x = 0; x < 16; x++) if (r[x] !== '.') rows[y][x] = r[x]; }); };
    lay(HANDS.jaws[jaw]); lay(HANDS.hair[hairKey], T.hat !== undefined ? T.hat + 1 : 0); lay(HANDS.facial[facial]); lay(HANDS.eyes[eyes]); lay(T.rows);   // headwear hides the hair above its brim
    return { rows: rows.map(r => r.join('')), pal, parts: { hairKey, jaw, facial, eyes, old } };
  }

